  NEXT_PROJECT_ROOT,
  'dist/build/webpack/loaders/instrumentation-client-stub.js'
)

export function createWebpackAliases({
  distDir,
  isClient,
  isEdgeServer,
  dev,
  config,
  pagesDir,
  appDir,
  dir,
  reactProductionProfiling,
